-- Strict 2PL: X lock held until COMMIT
BEGIN;
  UPDATE orders SET status = 'processing' WHERE id = 42;
  -- Row 42 is now X-locked; other writers block
  -- Basic 2PL could release lock here (risky)
  -- Strict 2PL holds the lock until...
COMMIT;  -- ← X lock released here (not before)

-- Cascading abort scenario prevented:
-- T2: SELECT * FROM orders WHERE id = 42;
-- With S2PL, T2 sees the old value until T1 commits.

// WAL commit sequence in pseudocode
int wal_fd = open("pg_wal/000000010000000000000001", O_RDWR);

// Write commit log record
write(wal_fd, commit_record, sizeof(commit_record));

// CRITICAL: fsync before acknowledging commit to client
// If this call fails, the commit must NOT be acknowledged
if (fsync(wal_fd) != 0) {
    handle_fsync_error();  // abort, do not reply success
}

// Only now is it safe to tell the client: commit confirmed
send_commit_ack(client);

-- PostgreSQL: Snapshot Isolation via REPEATABLE READ
BEGIN ISOLATION LEVEL REPEATABLE READ;
  -- Snapshot taken here: sees all commits before this point
  SELECT sum(balance) FROM accounts;  -- 1,000,000

  -- Concurrent T2 commits: INSERT INTO accounts VALUES (99, 500);
  -- Not visible to this transaction's snapshot

  SELECT sum(balance) FROM accounts;  -- still 1,000,000 (snapshot)
COMMIT;

-- Write skew example: on-call doctor system
-- T1 and T2 both run concurrently under REPEATABLE READ

-- T1:
BEGIN;
SELECT count(*) FROM on_call WHERE is_on_call = true; -- 2
-- Decides: safe to go off call
UPDATE on_call SET is_on_call = false WHERE doctor_id = 'alice';
COMMIT;

-- T2 (concurrent with T1):
BEGIN;
SELECT count(*) FROM on_call WHERE is_on_call = true; -- still 2 (snapshot)
UPDATE on_call SET is_on_call = false WHERE doctor_id = 'bob';
COMMIT; -- No conflict: different rows → both succeed
-- Result: 0 doctors on call. Invariant violated.

-- SSI in PostgreSQL: doctor on-call example resolved
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM on_call WHERE is_on_call = true; -- SIREAD lock
UPDATE on_call SET is_on_call = false WHERE doctor_id = 'alice';
COMMIT;

-- Concurrent T2 under SERIALIZABLE:
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT count(*) FROM on_call WHERE is_on_call = true; -- SIREAD lock
UPDATE on_call SET is_on_call = false WHERE doctor_id = 'bob';
COMMIT;
-- ERROR: could not serialize access due to read/write dependencies
-- One transaction aborts → invariant preserved
